// The /phone-exists-batch endpoint responds with an ARRAY: [{ exists, inputPhone, outputPhone }].
// Depending on the node version this array arrives as a single item or already flattened.
// This block normalizes both cases and treats a failed check as "does not exist"
// (fail-safe: better to fall back to SMS than to not deliver the OTP at all).
const first = $input.first().json;
const raw = Array.isArray(first) ? first[0] : (Array.isArray(first?.data) ? first.data[0] : first);

const exists = raw?.exists === true;
const phone = String(raw?.outputPhone || raw?.inputPhone || $('OTP request').first().json.body.phone);

return [{ json: { exists, phone, checkFailed: raw?.error !== undefined } }];
